package com.bananalab.lite;
import android.app.*;import android.os.*;import android.content.*;import java.io.*;import java.util.*;import java.util.zip.*;import org.json.*;
public final class Stage52Instrumentation extends Instrumentation{
 void check(boolean b,String s){if(!b)throw new AssertionError(s);}void note(String s){Bundle b=new Bundle();b.putString("stream",s+"\n");sendStatus(0,b);}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 BananaEngine.Result run(Context c,Semilla m,String q)throws Exception{return BananaEngine.run(c,q,new ArrayList<String[]>(),"",true,m);}
 String cmd(Context c,Semilla m,String q,String wanted)throws Exception{String text=run(c,m,q).text;check(text.contains(wanted),q+": "+text);return text;}
 @Override public void onStart(){Bundle out=new Bundle();try{Context c=getTargetContext();DurableCode.awaitReady();JavaProject.prefs(c).edit().clear().commit();ProjectRuntime.prefs(c).edit().clear().commit();PlannerExperience.prefs(c).edit().clear().commit();ProjectRuntime.restore(c);PlannerExperience.restore(c);Semilla m=OwnBrain.load(c);
 cmd(c,m,"prepara proyecto java","Copia Java");cmd(c,m,"edita metodo java AnimationProfile.java#jump: return -96f*t*(1f-t);","editada");cmd(c,m,"prepara sustitucion animacion","preparada");cmd(c,m,"aplica sustitucion java","Sustitución activa");cmd(c,m,"prepara sustitucion planificador","preparada");cmd(c,m,"aplica sustitucion java","Sustitución activa");check(ProjectRuntime.active.planner!=null,"compiled planner active");note("NATIVE_ALL_JAVA_COMPILES_NEW_PLANNER_ECJ_DX_TRIAL_AND_ACTIVATION_OK");
 run(c,m,"crea a Fito un zorro; agrega una banana llamada Bani");String design=MobileCore.scene(c).cast.get(0).designId;BananaEngine.Result plan=run(c,m,"fito arma una fiesta con bani");check(plan.changed&&plan.scene.actions.size()==3&&plan.scene.actions.get(0).equals("baila")&&plan.scene.actions.get(1).equals("salta"),"compiled planner actually creates recipe scene");check(plan.scene.cast.get(0).designId.equals(design),"design identity survives module planning");cmd(c,m,"ese plan esta bien","Aprendí");check(PlannerExperience.model!=null,"own weights learned automatically after explicit feedback");run(c,m,"fito arma una fiesta con bani");cmd(c,m,"ese plan esta mal","Aprendí");check(PlannerDispatch.plan("fito arma una fiesta con bani",MobileCore.scene(c),false)==null,"negative feedback produces learned abstention");cmd(c,m,"deshace aprendizaje planificador","Recuperé");check(PlannerDispatch.plan("fito arma una fiesta con bani",MobileCore.scene(c),false)!=null,"undo restores previous learned selection");PlannerDispatch.receipt.remove();note("NATIVE_REAL_SCENE_IDENTITY_OWN_WEIGHT_LEARNING_ABSTENTION_AND_UNDO_OK");
 JSONObject backup=DurableCode.portable(c);DurableCode.validate(c,backup);String before=ProjectRuntime.prefs(c).getString("active","{}");JSONObject damaged=new JSONObject(backup.toString());damaged.getJSONObject("modules").getJSONObject("planificador").put("sourceHash","alterado");try{DurableCode.importBackup(c,damaged);throw new AssertionError("invalid source identity imported");}catch(IOException expected){}check(before.equals(ProjectRuntime.prefs(c).getString("active","{}")),"invalid backup preserves active state");note("NATIVE_PORTABLE_SOURCE_JOURNAL_AND_TAMPER_REJECTION_OK");
 File capsule=new File(c.getExternalFilesDir(null),"owner.zip");check(capsule.isFile(),"owner capsule staged outside APK");String imported=ApkSigning.importKey(c,new FileInputStream(capsule));capsule.delete();check(imported.contains("protegida"),"owner certificate validated and imported");Object[] authority=ApkSigning.owner(c);check(authority[0] instanceof java.security.PrivateKey,"device-only wrapped signing authority decrypts");File built=DeviceApk.build(c);check(DeviceApk.prefs(c).getInt("lastVersion",0)==500001,"typed manifest version increment");try(ZipFile apk=new ZipFile(built)){check(apk.getEntry("assets/banana-code/planificador.jar")!=null&&apk.getEntry("assets/banana-code/animacion.jar")!=null,"compiled modules physically included in APK");check(apk.getEntry("assets/banana-code/sources/planificador/BananaProjectPatch.java")!=null,"canonical changed Java included in APK");check(apk.getEntry("assets/banana-code/manifest.json")!=null,"portable learning/code journal included");Enumeration<? extends ZipEntry> es=apk.entries();while(es.hasMoreElements()){String n=es.nextElement().getName();check(!n.endsWith(".pk8")&&!n.endsWith(".p12")&&!n.contains("owner.zip"),"no private key embedded");}}File copy=new File(c.getExternalFilesDir(null),"baked.apk");try(InputStream in=new FileInputStream(built);OutputStream target=new FileOutputStream(copy)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)target.write(b,0,n);}note("NATIVE_ANDROID_REPACKAGED_APK_WITH_COMPILED_CODE_V1_V2_V3_SIGNATURE_AND_OWNER_IDENTITY_OK");out.putString("stream","PASS STAGE52 real Android planner, local learned weights, portable source journal, device-only private key wrapping, APK repackaging, manifest version, signing and embedded code.\n");finish(Activity.RESULT_OK,out);}catch(Throwable e){StringWriter s=new StringWriter();e.printStackTrace(new PrintWriter(s));out.putString("stream","FAIL "+s);finish(Activity.RESULT_CANCELED,out);}}
}
